begin;
create table tongs.reference_clip_acquisition_operations(
 operation_id text primary key check(operation_id~'^forge:reference-clip:acquire:[a-zA-Z0-9._:-]{8,180}$'),operation_fingerprint text not null check(operation_fingerprint~'^[0-9a-f]{64}$'),
 workspace_id uuid not null,workpiece_id uuid not null,plan_revision_id uuid not null,plan_revision bigint not null,opportunity_id uuid not null,opportunity_revision_id uuid not null,opportunity_revision bigint not null,
 acquisition_type text not null check(acquisition_type in('upload','external_fetch')),state text not null check(state in('pending','source_acquired','video_asset_verified','poster_asset_verified','candidate_committed')),
 normalized_inputs_json jsonb not null,source_evidence_json jsonb,source_evidence_hash text,verified_video_asset_id uuid,verified_poster_asset_id uuid,result_candidate_revision_id uuid,
 failed_stage text,failure_code text,failure_message text,failure_evidence_json jsonb,receipt_json jsonb,created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 foreign key(plan_revision_id,workspace_id,workpiece_id,plan_revision) references tongs.reference_clip_plan_revisions(id,workspace_id,workpiece_id,revision),
 foreign key(opportunity_revision_id,workspace_id,workpiece_id,opportunity_id,opportunity_revision) references tongs.reference_clip_opportunity_revisions(id,workspace_id,workpiece_id,opportunity_id,revision),
 foreign key(verified_video_asset_id) references tongs.assets(id),foreign key(verified_poster_asset_id) references tongs.assets(id),foreign key(result_candidate_revision_id) references tongs.reference_clip_candidate_revisions(id),
 check((state='candidate_committed')=(receipt_json is not null)),check(state<>'source_acquired' or source_evidence_json is not null),check(state not in('video_asset_verified','poster_asset_verified','candidate_committed') or verified_video_asset_id is not null),check(state not in('poster_asset_verified','candidate_committed') or verified_poster_asset_id is not null)
);
alter table tongs.assets drop constraint assets_asset_kind_check,add constraint assets_asset_kind_check check(asset_kind in('thumbnail_image','thumbnail_composite','image_map_json','image_map_candidate_image','broll_candidate_video','broll_candidate_poster','reference_clip_video','reference_clip_poster'));
alter table tongs.assets drop constraint assets_kind_shape_check,add constraint assets_kind_shape_check check((asset_kind in('thumbnail_image','thumbnail_composite','broll_candidate_poster','reference_clip_poster')and mime_type like'image/%')or(asset_kind='image_map_json'and mime_type='application/json'and prompt is null)or(asset_kind='image_map_candidate_image'and mime_type like'image/%'and prompt is not null)or(asset_kind in('broll_candidate_video','reference_clip_video')and mime_type like'video/%'));
create unique index assets_reference_clip_acquisition_kind_idx on tongs.assets(workspace_id,workpiece_id,operation_id,asset_kind) where operation_id is not null and asset_kind in('reference_clip_video','reference_clip_poster');
create or replace function tongs.reject_verified_reference_clip_acquisition_mutation()returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin if old.state='candidate_committed' then raise exception 'verified Reference Clip acquisition is immutable' using errcode='55000';end if;return new;end$$;
create trigger reference_clip_acquisition_terminal before update or delete on tongs.reference_clip_acquisition_operations for each row execute function tongs.reject_verified_reference_clip_acquisition_mutation();

create or replace function tongs.begin_reference_clip_acquisition(p_workspace_id uuid,p_workpiece_id uuid,p_plan_revision_id uuid,p_plan_revision bigint,p_opportunity_id uuid,p_opportunity_revision_id uuid,p_opportunity_revision bigint,p_acquisition_type text,p_inputs jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_clip_acquisition_operations%rowtype;seq tongs.reference_clip_plan_sequences%rowtype;
begin if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if p_acquisition_type not in('upload','external_fetch') then return jsonb_build_object('disposition','unsupported_acquisition_type');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if found then if op.operation_fingerprint<>p_operation_fingerprint or op.workspace_id<>p_workspace_id or op.workpiece_id<>p_workpiece_id or op.opportunity_revision_id<>p_opportunity_revision_id or op.acquisition_type<>p_acquisition_type then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;if seq.current_plan_revision_id is distinct from p_plan_revision_id or seq.current_plan_revision<>p_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;perform 1 from tongs.reference_clip_plan_membership where plan_revision_id=p_plan_revision_id and opportunity_id=p_opportunity_id and opportunity_revision_id=p_opportunity_revision_id and opportunity_revision=p_opportunity_revision;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;
 insert into tongs.reference_clip_acquisition_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,plan_revision_id,plan_revision,opportunity_id,opportunity_revision_id,opportunity_revision,acquisition_type,state,normalized_inputs_json,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_plan_revision_id,p_plan_revision,p_opportunity_id,p_opportunity_revision_id,p_opportunity_revision,p_acquisition_type,'pending',p_inputs,p_actor_id)returning * into op;return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));end$$;

create or replace function tongs.record_reference_clip_source_acquired(p_operation_id text,p_operation_fingerprint text,p_source_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_clip_acquisition_operations%rowtype;h text;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;h:=encode(extensions.digest(convert_to(p_source_evidence::text,'UTF8'),'sha256'),'hex');if op.state<>'pending' then if op.source_evidence_hash<>h then return jsonb_build_object('disposition','source_evidence_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;update tongs.reference_clip_acquisition_operations set state='source_acquired',source_evidence_json=p_source_evidence,source_evidence_hash=h,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now() where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','source_acquired','operation',to_jsonb(op));end$$;

create or replace function tongs.commit_reference_clip_acquisition_asset(p_operation_id text,p_operation_fingerprint text,p_asset_kind text,p_path text,p_mime_type text,p_byte_size bigint,p_content_hash text,p_storage_bucket text,p_storage_key text,p_width integer,p_height integer,p_duration_ms bigint,p_provider text,p_provider_request_id text)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_clip_acquisition_operations%rowtype;a tongs.assets%rowtype;next_state text;begin if auth.role()<>'service_role' then raise exception 'Reference Clip asset commit requires service authority' using errcode='42501';end if;select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if p_asset_kind not in('reference_clip_video','reference_clip_poster') or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$' or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_media_evidence');end if;if p_asset_kind='reference_clip_video' and(p_mime_type not like 'video/%' or coalesce(p_duration_ms,0)<=0)then return jsonb_build_object('disposition','invalid_verified_video_evidence');end if;if p_asset_kind='reference_clip_poster' and p_mime_type not like 'image/%' then return jsonb_build_object('disposition','invalid_verified_poster_evidence');end if;
 select * into a from tongs.assets where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and operation_id=p_operation_id and asset_kind=p_asset_kind for update;if found then if a.operation_fingerprint<>p_operation_fingerprint or a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op),'asset',to_jsonb(a));end if;
 if p_asset_kind='reference_clip_video' and op.state<>'source_acquired' then return jsonb_build_object('disposition','source_acquisition_required');end if;if p_asset_kind='reference_clip_poster' and op.state<>'video_asset_verified' then return jsonb_build_object('disposition','video_asset_verification_required');end if;
 insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,p_provider,p_provider_request_id,p_operation_id,op.created_by,p_asset_kind,'ready',jsonb_strip_nulls(jsonb_build_object('duration_ms',p_duration_ms,'inspection_authority','tongs-service.v1')),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;next_state:=case when p_asset_kind='reference_clip_video' then 'video_asset_verified' else 'poster_asset_verified'end;update tongs.reference_clip_acquisition_operations set state=next_state,verified_video_asset_id=case when p_asset_kind='reference_clip_video' then a.id else verified_video_asset_id end,verified_poster_asset_id=case when p_asset_kind='reference_clip_poster' then a.id else verified_poster_asset_id end,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition',next_state,'operation',to_jsonb(op),'asset',to_jsonb(a));end$$;

create or replace function tongs.commit_reference_clip_acquisition_candidate(p_operation_id text,p_operation_fingerprint text,p_rights jsonb,p_provenance jsonb,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_clip_acquisition_operations%rowtype;o tongs.reference_clip_opportunity_revisions%rowtype;a tongs.assets%rowtype;c tongs.reference_clip_candidates%rowtype;r tongs.reference_clip_candidate_revisions%rowtype;h text;ih text;result jsonb;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return op.receipt_json;end if;if op.state<>'poster_asset_verified' then return jsonb_build_object('disposition','poster_asset_verification_required');end if;select * into o from tongs.reference_clip_opportunity_revisions where id=op.opportunity_revision_id;select * into a from tongs.assets where id=op.verified_video_asset_id and status='ready';if not found then return jsonb_build_object('disposition','verified_video_asset_required');end if;
 insert into tongs.reference_clip_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(op.workspace_id,op.workpiece_id,op.opportunity_id,p_actor_id)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset',a.content_hash,'poster',op.verified_poster_asset_id,'source',o.source_revision_id,'link',o.workpiece_source_link_revision_id,'rights',p_rights,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'hash',h,'revision',1,'operation',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,poster_asset_id,rights_basis,rights_holder,license_identifier,license_url,territories,expires_at,attribution_required,attribution_text,rights_evidence_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,op.workspace_id,op.workpiece_id,op.opportunity_id,1,o.id,o.revision,o.source_revision_id,o.source_revision,o.workpiece_source_link_revision_id,o.workpiece_source_link_revision,a.id,a.content_hash,a.path,a.storage_bucket,a.storage_key,a.mime_type,(a.metadata_json->>'duration_ms')::bigint,op.verified_poster_asset_id,coalesce(p_rights->>'basis','unknown'),p_rights->>'rights_holder',p_rights->>'license_identifier',p_rights->>'license_url',array(select jsonb_array_elements_text(coalesce(p_rights->'territories','[]'))),nullif(p_rights->>'expires_at','')::timestamptz,coalesce((p_rights->>'attribution_required')::boolean,false),p_rights->>'attribution_text',p_rights,p_provenance,h,ih,p_actor_id)returning * into r;result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(r),'operation_id',p_operation_id);update tongs.reference_clip_acquisition_operations set state='candidate_committed',result_candidate_revision_id=r.id,receipt_json=result,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now()where operation_id=p_operation_id returning * into op;return result;end$$;
create or replace function tongs.fail_reference_clip_acquisition(p_operation_id text,p_operation_fingerprint text,p_failed_stage text,p_failure_code text,p_failure_message text,p_failure_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_clip_acquisition_operations%rowtype;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return jsonb_build_object('disposition','terminal_operation','operation',to_jsonb(op));end if;update tongs.reference_clip_acquisition_operations set failed_stage=p_failed_stage,failure_code=p_failure_code,failure_message=p_failure_message,failure_evidence_json=p_failure_evidence,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','failure_recorded','operation',to_jsonb(op));end$$;
create or replace function tongs.read_reference_clip_acquisition(p_workspace_id uuid,p_operation_id text)returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$select case when not tongs.has_workspace_role(p_workspace_id,'viewer')then null else(select to_jsonb(o)from tongs.reference_clip_acquisition_operations o where o.workspace_id=p_workspace_id and o.operation_id=p_operation_id)end$$;
alter table tongs.reference_clip_acquisition_operations enable row level security;create policy reference_clip_acquisition_operations_viewer on tongs.reference_clip_acquisition_operations for select to authenticated using(tongs.has_workspace_role(workspace_id,'viewer'));revoke all on tongs.reference_clip_acquisition_operations from public,anon,authenticated;grant select on tongs.reference_clip_acquisition_operations to authenticated;
revoke all on function tongs.begin_reference_clip_acquisition(uuid,uuid,uuid,bigint,uuid,uuid,bigint,text,jsonb,text,text,uuid),tongs.record_reference_clip_source_acquired(text,text,jsonb),tongs.commit_reference_clip_acquisition_candidate(text,text,jsonb,jsonb,uuid),tongs.fail_reference_clip_acquisition(text,text,text,text,text,jsonb)from public,anon,authenticated;grant execute on function tongs.begin_reference_clip_acquisition(uuid,uuid,uuid,bigint,uuid,uuid,bigint,text,jsonb,text,text,uuid),tongs.record_reference_clip_source_acquired(text,text,jsonb),tongs.commit_reference_clip_acquisition_candidate(text,text,jsonb,jsonb,uuid),tongs.fail_reference_clip_acquisition(text,text,text,text,text,jsonb),tongs.read_reference_clip_acquisition(uuid,text)to authenticated,service_role;revoke all on function tongs.commit_reference_clip_acquisition_asset(text,text,text,text,text,bigint,text,text,text,integer,integer,bigint,text,text)from public,anon,authenticated;grant execute on function tongs.commit_reference_clip_acquisition_asset(text,text,text,text,text,bigint,text,text,text,integer,integer,bigint,text,text)to service_role;
commit;
